// 1. Sheet Data aur Keyword fetch karein
const sheetItems = $('Fetch Google Sheet Data').all().map(item => item.json);
const rawKeyword = $('Webhook Search Trigger').item.json.body?.keyword || 'Measuring Tape';
const searchKey = rawKeyword.toLowerCase().trim().replace(/s$/, '');

// 2. Fuzzy/Plural Matching Logic ("Measuring Tape" <-> "Measuring Tapes")
const matchedProducts = sheetItems.filter(product => {
  const name = (product['Product Name'] || product.Name || '').toLowerCase();
  const category = (product['Category'] || '').toLowerCase();

  return name.replace(/s$/, '').includes(searchKey) || category.replace(/s$/, '').includes(searchKey);
});

// 3. HTML Table Rows Build Karein
const tableRows = matchedProducts.length > 0 
  ? matchedProducts.map(p => `
      <tr>
        <td style="padding: 10px; border-bottom: 1px solid #ddd;">${p['Product Name'] || p.Name || ''}</td>
        <td style="padding: 10px; border-bottom: 1px solid #ddd;">${p.Category || 'Hardware'}</td>
        <td style="padding: 10px; border-bottom: 1px solid #ddd;">${p.Price || 'N/A'}</td>
      </tr>
    `).join('')
  : `<tr><td colspan="3" style="padding: 15px; text-align: center;">No items found</td></tr>`;

// 4. Clean HTML Output
const fullHtml = `<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; margin: 30px; color: #333; }
    h1 { color: #1a365d; }
    table { width: 100%; border-collapse: collapse; margin-top: 20px; }
    th { background: #2b6cb0; color: white; padding: 10px; text-align: left; }
  </style>
</head>
<body>
  <h1>B2B Hardware Catalog: ${rawKeyword}</h1>
  <table>
    <thead>
      <tr>
        <th>Product Name</th>
        <th>Category</th>
        <th>Price</th>
      </tr>
    </thead>
    <tbody>
      ${tableRows}
    </tbody>
  </table>
</body>
</html>`.trim();

return [{ json: { htmlTemplate: fullHtml } }];

// Input node se clean HTML retrieve karo
const rawHtml = $('General HTML').item.json.htmlTemplate || $('General HTML').item.json.source;
const cleanHtml = rawHtml.trim();

// PDFShift API Key
const apiKey = 'sk_b11b272b864770bf0cc97994d4b7009be9faa9ec';

try {
  // Built-in n8n HTTP Request helper
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.pdfshift.io/v3/convert/pdf',
    headers: {
      'Authorization': `Basic ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: {
      source: cleanHtml
    },
    encoding: 'arraybuffer'
  });

  const pdfBuffer = Buffer.from(response);

  return [{
    json: { success: true },
    binary: {
      data: {
        data: pdfBuffer.toString('base64'),
        mimeType: 'application/pdf',
        fileName: 'catalog.pdf'
      }
    }
  }];
} catch (error) {
  throw new Error(`PDFShift Conversion Error: ${error.message}`);
}

// 1. Extract Webhook Query Parameters & Sanitize Email
const queryParam = $('Webhook Search Trigger').first().json.query.search || '';
const maxPriceParam = parseFloat($('Webhook Search Trigger').first().json.query.maxPrice) || Infinity;

// Email Sanitization: Har tarah ke '=', extra quotes aur spaces ko clean karega
let rawEmail = $('Webhook Search Trigger').first().json.query.email || '';
let cleanEmail = String(rawEmail).replace(/[^a-zA-Z0-9@._-]/g, '').trim();

// Default fallback email address agar URL me param khali ho
if (!cleanEmail) {
  cleanEmail = "user@example.com";
}

const query = queryParam.toLowerCase().trim();

// 2. Fetch Google Sheet Records
const allItems = $input.all().map(item => item.json);

// 3. Apply Multi-Filter Criteria
const filtered = allItems.filter(p => {
  const name = (p['Product Name'] || '').toLowerCase();
  const category = (p['Category'] || '').toLowerCase();
  const price = parseFloat(p['Price (USD)']) || 0;

  const matchesQuery = name.includes(query) || category.includes(query);
  const matchesPrice = price <= maxPriceParam;

  return matchesQuery && matchesPrice;
});

// 4. Calculate Summary Metrics
const totalItems = filtered.length;
const totalCatalogValue = filtered.reduce((sum, item) => sum + (parseFloat(item['Price (USD)']) || 0), 0);
const currentDate = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

// 5. Construct HTML Table Rows
let tableRows = '';
if (totalItems === 0) {
  tableRows = `<tr><td colspan="5" style="text-align:center; padding: 25px; color: #64748B;">No products found matching "${queryParam}".</td></tr>`;
} else {
  filtered.forEach(p => {
    tableRows += `
      <tr style="border-bottom: 1px solid #E2E8F0;">
        <td style="padding:10px; text-align:center;"><img src="${p['Product Image URL']}" width="40" height="40" style="object-fit:contain; border-radius:4px;" /></td>
        <td style="padding:10px; font-weight:600; color:#1E293B;">${p['Product Name']}</td>
        <td style="padding:10px; font-size:12px; color:#64748B;">${p['SKU']}</td>
        <td style="padding:10px; font-weight:bold; color:#15803D;">$${p['Price (USD)']}</td>
        <td style="padding:10px; font-size:12px; color:#475569;">${p['Specifications']}</td>
      </tr>`;
  });
}

// 6. Enterprise HTML Catalog Layout
const htmlContent = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Helvetica Neue', Arial, sans-serif; margin: 0; padding: 30px; color: #1E293B; background: #ffffff; }
    .header { background: #1E3A8A; color: white; padding: 25px; border-radius: 8px; margin-bottom: 20px; }
    .header h1 { margin: 0; font-size: 24px; text-transform: uppercase; letter-spacing: 1px; }
    .header p { margin: 5px 0 0 0; font-size: 13px; opacity: 0.9; }
    .metrics-bar { display: flex; justify-content: space-between; background: #F8FAFC; border: 1px solid #E2E8F0; padding: 15px 20px; border-radius: 6px; margin-bottom: 25px; }
    .metric-item { text-align: center; }
    .metric-label { font-size: 11px; color: #64748B; text-transform: uppercase; font-weight: bold; }
    .metric-value { font-size: 18px; color: #1E3A8A; font-weight: bold; margin-top: 4px; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; margin-bottom: 30px; }
    th { background: #F1F5F9; color: #1E3A8A; text-align: left; padding: 12px 10px; border-bottom: 2px solid #CBD5E1; text-transform: uppercase; font-size: 11px; }
    .footer { text-align: center; font-size: 11px; color: #94A3B8; border-top: 1px solid #E2E8F0; padding-top: 15px; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Tuffix Hardware Catalog</h1>
    <p>Automated Product Export System</p>
  </div>

  <div class="metrics-bar">
    <div class="metric-item">
      <div class="metric-label">Date Generated</div>
      <div class="metric-value">${currentDate}</div>
    </div>
    <div class="metric-item">
      <div class="metric-label">Search Query</div>
      <div class="metric-value">"${queryParam || 'All Items'}"</div>
    </div>
    <div class="metric-item">
      <div class="metric-label">Items Found</div>
      <div class="metric-value">${totalItems}</div>
    </div>
    <div class="metric-item">
      <div class="metric-label">Total Value</div>
      <div class="metric-value">$${totalCatalogValue.toFixed(2)}</div>
    </div>
  </div>

  <table>
    <thead>
      <tr>
        <th>Image</th>
        <th>Product Name</th>
        <th>SKU</th>
        <th>Price</th>
        <th>Specifications</th>
      </tr>
    </thead>
    <tbody>
      ${tableRows}
    </tbody>
  </table>

  <div class="footer">
    Generated automatically by Tuffix Automated PDF Engine • Confidential
  </div>
</body>
</html>`;

return [{
  json: {
    html: htmlContent,
    searchQuery: queryParam || 'All Products',
    totalItems: totalItems,
    totalValue: totalCatalogValue.toFixed(2),
    recipientEmail: cleanEmail
  }
}];
